Example//Java Program to demonstrate why we need method overriding  
//Here, we are calling the method of parent class with child class object 
//Creating a parent class  
class Vehicle{  
  void run(){System.out.println("Vehicle is running");}  
}  
//Creating a child class  
class Bike extends Vehicle{}
//Creating a Main class to create object and call methods
public class Main{
  public static void main(String args[]){  
  //creating an instance of child class  
  Bike obj = new Bike();  
  //calling the method with child class instance  
  obj.run();  
  }  
}  
Compile and Run

Example//Java Program to illustrate the use of Java Method Overriding    
//Creating a parent class.    
class Vehicle{    
  //defining a method    
  void run(){System.out.println("Vehicle is running");}    
}    
//Creating a child class    
class Bike extends Vehicle{    
  //defining the same method as in the parent class    
  void run(){System.out.println("Bike is running safely");}   
}
//Creating a Main class to create object and call method
public class Main{ 
  public static void main(String args[]){    
  Bike obj = new Bike();//creating object    
  obj.run();//calling method    
  }    
}    
Compile and Run

Example//Java Program to demonstrate the real scenario of Java Method Overriding    
//where three classes are overriding the method of a parent class.    
//Creating a parent class.    
class Bank{    
int getRateOfInterest(){return 0;}    
}    
//Creating child classes    
class SBI extends Bank{    
int getRateOfInterest(){return 8;}    
}    
class ICICI extends Bank{    
int getRateOfInterest(){return 7;}    
}    
class AXIS extends Bank{    
int getRateOfInterest(){return 9;}    
}    
//Create a Main class to create objects and call the methods    
public class Main{    
public static void main(String args[]){    
SBI s=new SBI();    
ICICI i=new ICICI();    
AXIS a=new AXIS();    
System.out.println("SBI Rate of Interest: "+s.getRateOfInterest());    
System.out.println("ICICI Rate of Interest: "+i.getRateOfInterest());    
System.out.println("AXIS Rate of Interest: "+a.getRateOfInterest());    
}    
}  
Compile and Run

